from pathlib import Path
from PIL import Image
import ast, html, json, shutil, zipfile, re

R=Path(__file__).resolve().parents[1]; D=R/'ten-directions'
for p in D.glob('*.png'):
    if Image.open(p).format=='JPEG':p.rename(p.with_suffix('.jpg'))
new=json.loads((D/'route-briefs.json').read_text())
previous=json.loads((R/'illustrative-concepts/manifest.json').read_text())['routes']
extra={
 'saura-harvest':('Rice-white narrative figures and a communal hearth','Light sans-serif capitals; plain sans-serif for menu details.','The scene has fine limbs and grain details: reserve it for larger labels and prepare a simplified small symbol after selection.','https://sidac.odisha.gov.in/en/crafts-of-odisha','SIDAC — Saura painting','An original contemporary Saura-inspired cooking scene, not an authenticated Idital or a reproduced ritual composition.'),
 'patta-aroma':('Contour, paired birds and painted rice foliage','Warm serif capitals, supported by a clear sans-serif.','Keep contour and the rice-panicle motif at readable sizes; move finer decoration to larger packaging panels.','https://odisha.gov.in/en/odisha-tourism/patta-chitra','Government of Odisha — Patta Chitra','A secular contemporary illustration inspired by Pattachitra’s contour and narrative character; no traditional artist authorship is claimed.'),
 'pipili-feast':('Interlocking cutout shapes and festive colour','Bold rounded capitals and a simple sans-serif for practical copy.','Keep the large colour patches intact. Seam marks are supporting detail and can be omitted from a simplified production master.','https://odishatourism.gov.in/en/places/pipili','Odisha Tourism — Pipili','Digitally generated flat artwork inspired by appliqué’s assembly of coloured pieces; not a hand-stitched textile.'),
 'jhoti-rice':('Rice-paste-like linework and paddy sprigs','Soft, open capitals, with a restrained sans-serif information hierarchy.','Protect the pale linework with a plain dark field; a small solid alternative needs separate preparation.','https://odisha.gov.in/en/odisha-tourism/jhoti-chita-muruja','Government of Odisha — Jhoti, Chita, Muruja','An original rice-line illustration inspired by Jhoti Chita; it does not reproduce a household worship arrangement.'),
 'flat-layer':('Broad layers, rice rays and curved fields','Sturdy geometric sans-serif capitals; simple sans-serif information copy.','Keep the three layers and upper sun legible. Avoid adding extra rays or decorative strokes.','research/ten-directions-research.md','Design synthesis and research','A contemporary flat illustration with no traditional-art attribution.'),
 'negative-aroma':('One strong silhouette and one readable cutout','Quiet sans-serif capitals so the symbol carries the visual surprise.','Never fill the pale pot-and-steam cutout. Test at actual size before commissioning a small-format master.','research/ten-directions-research.md','Design synthesis and research','A contemporary negative-space exploration: its meaning is an original design proposal, not a historical symbol.'),
 'golden-aroma':('Related circular arcs and an aroma spiral','Restrained rounded capitals; functional sans-serif supporting copy.','Keep the spiral open. Do not add a decorative Fibonacci grid as proof of construction.','research/ten-directions-research.md','Geometry note and research','Golden-ratio-inspired geometric study. Exact φ proportions are not verified in the generated raster; a measured vector construction is needed for an exact claim.')
}
names={
 'saura-harvest':['Clay','Rice white','Seed ochre'], 'patta-aroma':['Peacock teal','Vermilion','Harvest gold','Parchment'],
 'pipili-feast':['Night indigo','Crimson','Marigold','Cloth cream'], 'jhoti-rice':['Mulberry','Rice white','Earth gold'],
 'flat-layer':['Paprika','Sea teal','Sun yellow','Warm cream'], 'negative-aroma':['Forest','Grain gold','Rice cream'],
 'golden-aroma':['Deep blue','Copper','Warm ivory']}
roles={
 'saura-harvest':['Primary clay field','Figures, pot outline and lettering','Rice, food and hearth accents'],
 'patta-aroma':['Pot, foliage and lettering','Paired birds and narrative accents','Grain and small ornamental accents','Main paper field'],
 'pipili-feast':['Lid and primary lettering','Pot outlines, patches and ODISHA line','Contrasting patchwork fills','Background and hand cutouts'],
 'jhoti-rice':['Primary background field','Pot, paddy linework and lettering','Small grain accents'],
 'flat-layer':['Pot silhouette','Handles and lettering','Layered sun and rice rays','Main neutral layout field'],
 'negative-aroma':['Leaf-like silhouette and lettering','Single grain accent','Negative-space pot and background'],
 'golden-aroma':['Spiral, rim and lettering','Warm pot silhouette','Background and open counters']}
routes=[]
for c in new:
    x=extra[c['slug']]
    c.update(title=c['name'],theme=c['family'],detail=x[0],type=x[1],small=x[2],source=x[3],source_name=x[4],boundary=x[5],origin='New in revision 08',group='tradition' if c['n']<=4 else 'modern')
    c['palette']=[(name,col,roles[c['slug']][i]) for i,(name,col) in enumerate(zip(names[c['slug']],c['colors']))]
    routes.append(c)
for number,slug in [(5,'shared-handi'),(6,'garden-handi'),(10,'dum-host')]:
    c=next(x.copy() for x in previous if x['slug']==slug)
    c.update(n=number,name=c['title'],family=c['theme'],idea=c['meaning'],grammar=c['grammar'],type=c['type'],detail=c['theme'],small='Keep the main gesture clear. Fine details and tagline need actual-size testing; prepare a simplified small-format master after selection.',origin='Developed in revision 07; retained in this collection',group='modern' if number==10 else 'tradition')
    for kind in ['logo','mockup']:shutil.copy2(R/f'illustrative-concepts/{slug}-{kind}.jpg',D/f'{slug}-{kind}.jpg')
    routes.append(c)
routes.sort(key=lambda c:c['n'])
assert len(routes)==10 and len({c['slug'] for c in routes})==10
# Reuse the existing, self-contained guide typography and responsive layout.
tree=ast.parse((R/'scripts/illustrative_guides.py').read_text())
css=next(ast.literal_eval(node.value) for node in tree.body if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CSS' for t in node.targets))
css+=''' .catalogue{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:42px 30px}.catalogue h2{font-size:31px}.catalogue img{border:1px solid #e3d8c6}.filters{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.filters button{font:inherit;padding:10px 18px;border:1px solid #943d31;background:transparent;color:#943d31;cursor:pointer}.filters button[aria-pressed=true]{background:#943d31;color:#fff9ef}.filters button:focus-visible{outline:3px solid #d99c38;outline-offset:3px}[hidden]{display:none!important}.mini{max-width:240px}.two{grid-template-columns:1fr 1fr}.nav-next{display:flex;justify-content:space-between;gap:20px}.badge{display:inline-block;padding:4px 10px;background:#eee6d8;font-size:12px}@media(max-width:750px){.catalogue{grid-template-columns:1fr}}'''
def page(title,body,ink='#943d31',script=''):
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{css}</style></head><body style="--ink:{ink}"><main>{body}</main>{script}</body></html>'
def asset(c,kind):
    for suffix in ['.jpg','.png']:
        p=D/f'{c["slug"]}-{kind}{suffix}'
        if p.is_file():return p
    raise FileNotFoundError(c['slug']+' '+kind)
def img(c,kind,alt):
    p=asset(c,kind);w,h=Image.open(p).size
    return f'<img src="ten-directions/{p.name}" width="{w}" height="{h}" alt="{html.escape(alt)}" loading="lazy">'
def url(c):return f'brand-concept-{c["n"]:02}-{c["slug"]}.html'
for i,c in enumerate(routes):
    sw=''.join(f'<article><div class="swatch" style="background:{h}"></div><strong>{n}</strong><br><code>{h}</code><p>{role}</p></article>' for n,h,role in c['palette'])
    nav=f'<nav><a href="brand-review.html">← All 10 concepts</a><a href="#packaging">Packaging</a><a href="#system">Brand system</a><a href="brand-audit.html">Research</a><a href="brand-history.html">History</a></nav>'
    nextc=routes[(i+1)%10]
    b=nav+f'''<header><div class="eyebrow">Dum E Odisha / Concept {c['n']:02} of 10 / Revision 08</div><h1>{c['title']}</h1><p class="lead">{c['theme']}</p><p class="small">{c['origin']}</p></header><div class="grid"><figure>{img(c,'logo',c['title']+' logo for Dum E Odisha')}</figure><div><h2>The meaning in the mark.</h2><p>{c['meaning']}</p><p><strong>Brand:</strong> Dum E Odisha<br><strong>Tagline:</strong> Flavour in Every Layer.</p><p><strong>Positioning:</strong> A welcoming biryani specialist, offering flavour and variety for everyday cravings and shared meals.</p><h3>The visual idea</h3><p>{c['detail']}</p><a class="button" href="ten-directions/{c['slug']}-logo.jpg" download>Download this logo study</a></div></div><section id="packaging"><div class="eyebrow">Illustration becomes a visual world</div><h2>A distinct packaging language.</h2><figure>{img(c,'mockup',c['title']+' bag and biryani container packaging mockup')}<figcaption>Illustrative application concept created with Nano Banana. Materials, food, menu details and any prices shown are sample content, not confirmed business specifications.</figcaption></figure><p>{c['grammar']}</p><a href="ten-directions/{c['slug']}-mockup.jpg" download>Download packaging mockup</a></section><section id="system"><h2>Colour, with a purpose.</h2><div class="palette">{sw}</div><p class="small">HEX values are design targets. Generated raster tones vary; these are not ink separations or press specifications. Use this route’s palette together rather than mixing colours across the ten identities.</p></section><section><div class="grid"><div><h2>Type & voice.</h2><p>{c['type']} The logo is generated artwork, with no exact font match claimed. Do not retype it as a substitute for the supplied design.</p><p>Write <strong>Dum E Odisha</strong> consistently. Preserve the spaces around E and keep Odisha integral to the name. Biryani describes the offer outside the official logo.</p><p>Voice: warm, direct and appetite-led. “Find your favourite. Share a biryani.” Use <em>Flavour in Every Layer.</em> in larger layouts where it remains readable.</p></div><div class="panel"><h3>Use rules</h3><ul><li>Keep the complete mark and its proportions intact.</li><li>Leave a margin of at least one capital D height around the visible logo as a working layout rule.</li><li>Place the logo on a plain field; keep secondary illustration on separate panels.</li><li>Avoid shadows, gradients, stretching and extra decoration.</li><li>{c['small']}</li></ul></div></div></section><section><h2>Reference, interpreted.</h2><p>{c['boundary']}</p><p><a href="{c['source']}">{c['source_name']}</a> · <a href="research/ten-directions-research.md">Research for the full collection</a></p></section><section><h2>A quick scale comparison.</h2><div class="grid"><div><p>Full artwork at a reduced layout size. This is a viewing comparison, not a validated minimum-size claim.</p><figure class="mini">{img(c,'logo',c['title']+' logo shown at reduced layout size')}</figure></div><div><p>Before production, prepare a clean vector master, a simple one-ink version and an appropriate small-format symbol. Check the real label or sign at its intended size.</p><p>Current deliverables are high-resolution raster concept studies with opaque backgrounds. No transparent master, print dieline or exact geometric certification is included.</p></div></div></section><footer class="nav-next"><a href="brand-review.html">← Back to all 10</a><a href="{url(nextc)}">Next: {nextc['title']} →</a></footer>'''
    b=b.replace(f'ten-directions/{c["slug"]}-logo.jpg',f'ten-directions/{asset(c,"logo").name}').replace(f'ten-directions/{c["slug"]}-mockup.jpg',f'ten-directions/{asset(c,"mockup").name}')
    (R/url(c)).write_text(page('Dum E Odisha — '+c['title'],b,c['palette'][0][1]))
cards=''.join(f'''<article data-group="{c['group']}"><a href="{url(c)}">{img(c,'logo',f'Concept {c["n"]:02}: '+c['title'])}</a><p class="eyebrow">{c['n']:02} / {c['theme']}</p><h2>{c['title']}</h2><p>{c['meaning']}</p><a class="button" href="{url(c)}">Open this brand guide →</a></article>''' for c in routes)
body='''<nav><a href="#collection">Ten concepts</a><a href="#compare">Compare the approaches</a><a href="brand-audit.html">Research</a><a href="brand-history.html">Earlier designs</a></nav><header><div class="eyebrow">Dum E Odisha / 10 distinct identities / Revision 08</div><h1>Ten stories.<br>One love of biryani.</h1><p class="lead">Traditional craft references and contemporary symbols, explored through ten different logos and complete visual directions.</p><p>Each concept has its own logo, colour palette, type direction, illustration language, use rules and packaging mockup. Seven new directions join the three developed illustrated identities. The full name remains <strong>Dum E Odisha</strong>; the common tagline is <strong>Flavour in Every Layer.</strong></p><a class="button" href="ten-directions/dum-e-odisha-ten-brand-guides.zip" download>Download all 10 brand guides & assets</a></header><section id="collection"><h2>Explore the collection.</h2><div class="filters" aria-label="Concept categories"><button data-filter="all" aria-pressed="true">All 10</button><button data-filter="tradition" aria-pressed="false">Craft & cultural references · 6</button><button data-filter="modern" aria-pressed="false">Modern approaches · 4</button></div><p id="concept-count" class="small" aria-live="polite">Showing all 10 concepts</p><div class="catalogue">'''+cards+'''</div></section><section id="compare"><h2>Choose the story, then the style.</h2><table><tr><th>Approach</th><th>What distinguishes it</th></tr><tr><td>01 · Harvest & Hearth</td><td>Saura-inspired fine narrative figures and communal cooking</td></tr><tr><td>02 · The Painted Handi</td><td>Pattachitra-inspired contours, birds and rich rice foliage</td></tr><tr><td>03 · The Patchwork Feast</td><td>Pipili-inspired interlocking patches and festive colour</td></tr><tr><td>04 · The Rice Welcome</td><td>Jhoti Chita-inspired pale grain linework on mulberry</td></tr><tr><td>05 · The Shared Handi</td><td>Broad human silhouettes embracing a meal</td></tr><tr><td>06 · The Dum Garden</td><td>Mughal botanical-inspired flowering handi</td></tr><tr><td>07 · The Layered Sun</td><td>Modern flat layers, warmth and a sun-shaped rice rhythm</td></tr><tr><td>08 · The Hidden Handi</td><td>Pot-and-aroma cutout inside a leaf-like silhouette</td></tr><tr><td>09 · The Spiral of Dum</td><td>Golden-ratio-inspired circular proportions and a rising aroma spiral</td></tr><tr><td>10 · The Dum Keeper</td><td>Illustrated cook holding a fragrant handi</td></tr></table><p>These are separate identity routes. Pick a story and visual language before refining lettering, small-size variants and production artwork.</p></section><section><h2>Craft references with clear context.</h2><p>The traditional routes are original AI-created interpretations, labelled as inspired studies. They do not claim traditional artisan authorship. The geometry route explores proportion without claiming a measured golden-ratio construction.</p><p><a href="brand-audit.html">Read the source research and design decisions →</a></p></section><footer><a href="brand-history.html">Earlier designs remain available</a> · <a href="brand-review-round07.html">Previous three-concept collection</a></footer>'''
js='''<script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const f=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('[data-group]').forEach(c=>{c.hidden=f!=='all'&&c.dataset.group!==f;if(!c.hidden)n++});document.getElementById('concept-count').textContent='Showing '+n+' concepts';}));</script>'''
(R/'brand-review.html').write_text(page('Dum E Odisha — Ten logos and brand guides',body,script=js))
audit='''<nav><a href="brand-review.html">← Ten brand guides</a><a href="brand-history.html">Earlier work</a></nav><header><div class="eyebrow">Research / Revision 08</div><h1>Different traditions.<br>Different visual languages.</h1><p class="lead">Fine narrative figures, painted contours, cut-cloth shapes and rice-paste lines should produce different designs.</p></header><section><h2>What informed the collection</h2><table><tr><th>Reference</th><th>Translation into the concepts</th></tr><tr><td><a href="https://sidac.odisha.gov.in/en/crafts-of-odisha">Saura — SIDAC</a></td><td>Abstract figures, nature and community inform an original secular cooking scene. The work is labelled inspired, not authenticated Idital.</td></tr><tr><td><a href="https://odisha.gov.in/en/odisha-tourism/patta-chitra">Pattachitra — Government of Odisha</a></td><td>Flat colour, contour and narrative decoration inform the birds, rice foliage and painted vessel.</td></tr><tr><td><a href="https://odishatourism.gov.in/en/places/pipili">Pipili — Odisha Tourism</a></td><td>Cut pieces and stitched assembly inform large interlocking colour shapes and scalloped panels.</td></tr><tr><td><a href="https://odisha.gov.in/en/odisha-tourism/jhoti-chita-muruja">Jhoti Chita — Government of Odisha</a></td><td>Rice-paste linework and paddy imagery inform a secular rice-and-pot illustration.</td></tr><tr><td><a href="https://www.metmuseum.org/art/collection/search/838376">Mughal botanicals — The Met</a></td><td>Balanced plants and hybrid flowers inform the Dum Garden; this is a separate courtly art reference.</td></tr><tr><td><a href="https://kruticoffee.com/pages/about-us">Kruti Coffee — official story</a></td><td>A meaningful story should connect the mark and wider product system. Dum E Odisha’s proposed stories concern cooking, flavour and sharing.</td></tr></table><p><a href="research/ten-directions-research.md">Full primary-source research</a> · <a href="research/ten-logo-briefs.json">New logo prompts</a> · <a href="research/ten-mockup-briefs.json">New mockup prompts</a></p></section><section><h2>What stays consistent</h2><p>The name is Dum E Odisha, with a clear separation around E. The tagline is Flavour in Every Layer. Each route has its own palette and illustration grammar; the routes are alternatives rather than interchangeable brand variants.</p></section><section><h2>Geometry and delivery</h2><p>The Spiral of Dum is a golden-ratio-inspired geometric study. The generated raster is not evidence of exact φ proportions. A documented vector construction would be required for that claim.</p><p>All new visuals were generated through Nano Banana MCP. Logos and mockups are visually checked for spelling, separation, meaning and consistency. Local files and guide references are validated; no fresh browser-render check is claimed. Raster concepts need production masters and physical proofs before manufacture.</p></section><footer><a href="brand-audit-round07.html">Previous research page</a> · <a href="brand-review.html">Explore all 10</a></footer>'''
(R/'brand-audit.html').write_text(page('Dum E Odisha — Research for ten identities',audit))
h=R/'brand-history.html';s=h.read_text()
if 'id="round07"' not in s:
    s=s.replace('<section id="round06">','<section id="round07"><h2>Revision 07 — first three illustrated identities</h2><p>Shared Handi, Dum Garden and Dum Keeper were developed in this round. They remain part of the expanded collection, alongside seven new directions.</p><a href="brand-review-round07.html">View the three-concept collection</a> · <a href="brand-audit-round07.html">Research for that round</a></section><section id="round06">',1);h.write_text(s)
manifest={'brand_name':'Dum E Odisha','revision':'08','status':'Ten concept routes; no final route selected','tagline':'Flavour in Every Layer.','routes':routes,'files':[]}
for c in routes:
    for kind in ['logo','mockup']:
        p=asset(c,kind);im=Image.open(p);im.verify()
        manifest['files'].append({'file':p.name,'width':im.width,'height':im.height,'format':im.format})
(D/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
(R/'docs/identity.json').write_text(json.dumps({'brand_name':'Dum E Odisha','revision':'08','status':manifest['status'],'tagline':manifest['tagline'],'concept_manifest':'ten-directions/manifest.json','previous_identity':'docs/identity-round07.json','guide':'brand-review.html'},indent=2)+'\n')
with zipfile.ZipFile(D/'dum-e-odisha-ten-brand-guides.zip','w',zipfile.ZIP_DEFLATED) as z:
    for f in manifest['files']:z.write(D/f['file'],'ten-directions/'+f['file'])
    z.write(D/'manifest.json','ten-directions/manifest.json')
    for name in ['ten-directions-research.md','illustrative-directions-research.md','ten-logo-briefs.json','ten-mockup-briefs.json']:
        z.write(R/'research'/name,'research/'+name)
    for name in ['brand-review.html','brand-audit.html']+[url(c) for c in routes]:
        text=(R/name).read_text()
        text=re.sub(r'<a\b[^>]*href="brand-(?:history|review-round07|audit-round07)\.html"[^>]*>.*?</a>','',text,flags=re.S)
        text=re.sub(r'<a\b[^>]*href="ten-directions/dum-e-odisha-ten-brand-guides\.zip"[^>]*>.*?</a>','',text,flags=re.S)
        z.writestr(name,text)
    z.writestr('README.txt','DUM E ODISHA — Ten identity concepts\nOpen brand-review.html to compare, then follow each individual guide.\nIncludes 10 logo studies, 10 packaging mockups, 10 individual guides and source research.\nSeven new concepts plus three developed in revision 07.\nAll new visual artwork generated through Nano Banana MCP.\nHigh-resolution JPEG concepts with opaque backgrounds; not production vector masters or dielines.\nGolden-ratio-inspired geometry is not a certified exact construction.\nTraditional routes are contemporary inspired studies, not artisan-authored work.\n')
print('Built ten individual guides, collection, research, history and complete offline package.')
